// Escolhas do personagem e KC fazem parte do progresso privado da própria conta.
let avatarDraft=null,kcPendingProduct=null;
function kcHistoryLabel(kind){return {earned:'Atividade aprovada',energy:'Recarga de energia',xp:'Bônus de XP ativado',boost:'Bônus de XP usado'}[kind]||'Movimento de KC';}
function kcShopPage(){const E=DojoEconomy,w=state.wallet;return `<section class="animate-in kc-shop"><span class="eyebrow">SEU ESFORÇO VIRA NOVAS POSSIBILIDADES</span><h1>Kyokushin Coins</h1><p class="intro">Aprenda, junte KC e escolha seu próximo impulso.</p><div class="kc-balance-card"><span class="kc-coin" aria-hidden="true">KC</span><div><small>SEU SALDO</small><strong>${w.balance.toLocaleString('pt-BR')} <span>KC</span></strong><p>+10 KC por fase aprovada, uma vez por dia para cada fase.</p></div></div>${w.boostRemaining?`<div class="kc-active"><b>✦ Seu impulso está ativo</b><span>+10 XP nas próximas ${w.boostRemaining} fases aprovadas com recompensa disponível.</span></div>`:''}<div class="kc-products">${E.PRODUCTS.map(p=>{const ready=E.availability(w,state.game,p.id);return `<article class="kc-product"><span class="kc-product-icon" aria-hidden="true">${p.kind==='energy'?'ϟ':'✦'}</span><h2>${p.name}</h2><p>${p.description}</p><b class="kc-price">${p.price} KC</b><button class="primary" data-kc-product="${p.id}" ${ready.ok?'':'disabled'}>Trocar por ${p.price} KC →</button><small>${ready.ok?'Você confirma antes de gastar.':esc(ready.reason)}</small></article>`;}).join('')}</div><div class="info-panel kc-rules"><h2>Como funciona</h2><p>Uma fase aprovada rende 10 KC no primeiro recebimento do dia. Repetir a mesma fase hoje ou ficar abaixo da nota mínima não rende KC. Você pode estudar outras fases para juntar mais.</p><p>A recarga acrescenta 5 energias até o limite de 25. O impulso acrescenta 10 XP a cada uma das próximas 3 fases aprovadas que ainda tenham recompensa no dia. Revisões sem recompensa e tentativas não aprovadas conservam os bônus para depois.</p><p>KC são moedas virtuais de aprendizado, sem valor em dinheiro, compra com dinheiro real, saque ou transferência entre alunos. Bônus não aprovam fases nem mudam sua faixa real.</p></div><details class="info-panel kc-history"><summary>Meus movimentos recentes</summary>${w.history.length?`<ol>${w.history.slice().reverse().map(h=>`<li><div><b>${kcHistoryLabel(h.kind)}</b><small>${new Date(h.at).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></div><strong>${h.coins>0?'+':''}${h.coins} KC</strong></li>`).join('')}</ol>`:'<p>Suas recompensas e trocas vão aparecer aqui.</p>'}</details><button class="outline" data-view="home">Escolher uma atividade →</button></section>`;}
function playerProfileCard(){const a=DojoAvatar.normalize(state.avatar);return `<div class="info-panel player-profile-card"><div class="player-profile-portrait">${DojoAvatar.svg(a)}</div><div><span class="eyebrow">SEU KARATECA</span><h2>${a.configured?'Meu avatar':'Monte seu avatar'}</h2><p>${a.configured?'Faixa real informada: '+esc(G.BELTS[a.belt].name):'Escolha personagem, cabelo e sua faixa real no San Dojo.'}</p><button class="outline" data-view="avatar">${a.configured?'Editar':'Criar'} meu avatar →</button><button class="text-button" data-view="shop">Minha carteira · ${state.wallet.balance} KC →</button></div></div>`;}
function avatarPage(){const V=DojoAvatar,a=V.normalize(state.avatar);const select=(key,label)=>`<label>${label}<select name="${key}" data-avatar-field>${V.OPTIONS[key].map(([id,text])=>`<option value="${id}" ${a[key]===id?'selected':''}>${text}</option>`).join('')}</select></label>`;return `<section class="animate-in avatar-page"><span class="eyebrow">COM O SEU JEITO, COM A SUA FAIXA</span><h1>Meu karateca</h1><p class="intro">Monte seu personagem e coloque a faixa que você usa no San Dojo.</p><div class="avatar-editor"><div class="avatar-preview-card"><div id="avatar-live-preview">${V.svg(a)}</div><span class="avatar-preview-label">SUA PRÉVIA</span><p id="avatar-real-belt">Faixa real: ${esc(G.BELTS[a.belt].name)}</p></div><form id="avatar-form" class="avatar-form"><fieldset><legend>Tipo de personagem</legend><div class="avatar-character-options">${V.OPTIONS.character.map(([id,label])=>`<button type="button" data-avatar-character="${id}" aria-pressed="${a.character===id}">${label}</button>`).join('')}</div></fieldset><div class="avatar-field-grid">${select('hair','Cabelo')}${select('hairColor','Cor do cabelo')}${select('skin','Tom de pele')}${select('expression','Expressão')}</div><label>Minha faixa real no San Dojo<select name="belt" data-avatar-field>${G.BELTS.map((b,i)=>`<option value="${i}" ${a.belt===i?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><p class="week-note">Essa é a faixa real informada por você. Ela aparece no avatar e no perfil. A faixa ilustrativa das atividades continua seguindo seu aprendizado no app.</p><div class="avatar-actions"><button class="primary" type="submit">Salvar meu avatar →</button><button class="text-button" type="button" data-view="account">Cancelar</button></div><p class="week-note">Suas escolhas ficam na sua conta. O avatar não é um perfil público.</p></form></div></section>`;}
function refreshAvatarDraft(){const root=document.getElementById('avatar-live-preview');if(!root||!avatarDraft)return;root.innerHTML=DojoAvatar.svg(avatarDraft);document.getElementById('avatar-real-belt').textContent='Faixa real: '+G.BELTS[avatarDraft.belt].name;document.querySelectorAll('[data-avatar-character]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.avatarCharacter===avatarDraft.character)));}
function mountAvatarEditor(){avatarDraft=DojoAvatar.normalize(state.avatar);}
function openKCConfirmation(id){if(!DojoAccounts.canStudy())return;const p=DojoEconomy.PRODUCTS.find(p=>p.id===id);if(!p)return;const ready=DojoEconomy.availability(state.wallet,state.game,id);if(!ready.ok){toast(ready.reason);return;}kcPendingProduct=id;const dialog=document.getElementById('kc-purchase-dialog');document.getElementById('kc-purchase-content').innerHTML=`<span class="eyebrow">UMA TROCA, UM NOVO PASSO</span><h2>${p.name}</h2><p>${p.description}</p><p>Você vai usar <strong>${p.price} KC</strong>. Seu saldo ficará em <strong>${state.wallet.balance-p.price} KC</strong>.</p><div class="avatar-actions"><button type="button" class="primary" data-kc-confirm>Confirmar troca →</button><button type="button" class="text-button" data-kc-cancel>Voltar</button></div>`;dialog.showModal();}
function confirmKCPurchase(){const id=kcPendingProduct;if(!id)return;kcPendingProduct=null;const dialog=document.getElementById('kc-purchase-dialog');if(!DojoAccounts.canStudy()){dialog.close();return;}const result=DojoEconomy.purchase(state.wallet,state.game,id);if(!result.ok){dialog.close();toast(result.reason);return;}save();dialog.close();render('shop');toast(result.product.kind==='energy'?'+5 energias! Seu próximo treino está esperando.':'Impulso ativo: +10 XP nas próximas 3 fases aprovadas com recompensa.');}
document.addEventListener('click',event=>{const target=event.target,b=target.closest('[data-avatar-character]');if(b){if(!avatarDraft)return;avatarDraft=DojoAvatar.normalize({...avatarDraft,character:b.dataset.avatarCharacter});refreshAvatarDraft();return;}const product=target.closest('[data-kc-product]');if(product){openKCConfirmation(product.dataset.kcProduct);return;}if(target.closest('[data-kc-confirm]')){confirmKCPurchase();return;}if(target.closest('[data-kc-cancel]')){kcPendingProduct=null;document.getElementById('kc-purchase-dialog').close();return;}if(target.closest('[data-finish-shop]')){document.getElementById('lesson').close();go('shop');return;}if(target.closest('[data-kc-energy-shop]')){document.getElementById('energy-dialog').close();go('shop');}});
document.addEventListener('change',event=>{if(!event.target.matches('[data-avatar-field]')||!avatarDraft)return;const {name,value}=event.target;avatarDraft=DojoAvatar.normalize({...avatarDraft,[name]:name==='belt'?Number(value):value});refreshAvatarDraft();});
document.addEventListener('submit',event=>{if(event.target.id!=='avatar-form')return;event.preventDefault();if(!DojoAccounts.canStudy())return;state.avatar=DojoAvatar.normalize({...avatarDraft,configured:true});save();go('account');toast('Seu avatar foi salvo. Osu!');});
